//! Golden-vector differential validation for the time-dynamic property
//! chain (task #33 / audit f7 Blocker 1).
//!
//! The reference values below were generated by running the ORIGINAL
//! CesiumJS implementations (`packages/engine/Source/DataSources/
//! SampledProperty.js` and `TimeIntervalCollectionProperty.js`) via Node
//! (`target/gen_golden.mjs` → `target/golden_utf8.json`).
//!
//! Alignment policy per the task contract:
//! - algebraic pipelines (linear interpolation, packed storage, interval
//!   lookups, extrapolation control flow) are asserted bit-exact;
//! - transcendental/polynomial pipelines (Hermite and Lagrange evaluation)
//!   are asserted within ≤ 2 ULP via `assert_epsilon_eq_f64!`.

use cesium_core::extrapolation_type::ExtrapolationType;
use cesium_data_sources::property::PropertyResult;
use cesium_data_sources::sampled_property::{
    InterpolationAlgorithmKind, PackableType, SampledProperty,
};
use cesium_data_sources::time_interval_collection_property::{
    PropertyTimeInterval, TimeIntervalCollectionProperty,
};
use cesium_test_utils::assert_epsilon_eq_f64;

const DAY: f64 = 86400.0;

fn number(value: f64) -> PropertyResult {
    PropertyResult::Number(value)
}

fn cartesian3(x: f64, y: f64, z: f64) -> PropertyResult {
    PropertyResult::Cartesian3(x, y, z)
}

fn expect_number(result: Option<PropertyResult>) -> Option<f64> {
    match result {
        None => None,
        Some(PropertyResult::Number(value)) => Some(value),
        Some(other) => panic!("expected Number, got {:?}", other),
    }
}

fn expect_cartesian3(result: Option<PropertyResult>) -> Option<[f64; 3]> {
    match result {
        None => None,
        Some(PropertyResult::Cartesian3(x, y, z)) => Some([x, y, z]),
        Some(other) => panic!("expected Cartesian3, got {:?}", other),
    }
}

// ---------------------------------------------------------------------------
// case 1: linear numeric samples — bit-exact
// ---------------------------------------------------------------------------

#[test]
fn golden_linear_number_is_bit_exact() {
    let mut property = SampledProperty::new(PackableType::Number);
    property.add_sample(0.0, &number(7.0));
    property.add_sample(DAY, &number(8.0));
    property.add_sample(2.0 * DAY, &number(9.0));

    // (t, golden v) — None mirrors JS `undefined`.
    let expected: [(f64, Option<f64>); 7] = [
        (-1.0, None),
        (0.0, Some(7.0)),
        (43200.0, Some(7.5)),
        (86400.0, Some(8.0)),
        (129600.0, Some(8.5)),
        (172800.0, Some(9.0)),
        (200000.0, None),
    ];
    for (t, expected) in expected {
        assert_eq!(
            expect_number(property.get_value_option(t)),
            expected,
            "t = {}",
            t
        );
    }
}

// ---------------------------------------------------------------------------
// case 2: packed array with epoch + out-of-order addSample — bit-exact
// ---------------------------------------------------------------------------

#[test]
fn golden_packed_epoch_is_bit_exact() {
    let mut property = SampledProperty::new(PackableType::Number);
    property.add_samples_packed_array(&[0.0, 7.0, 1.0, 8.0, 2.0, 9.0], Some(0.0));
    // samples can be added in any order
    property.add_sample(0.5, &number(10.5));

    let expected: [(f64, Option<f64>); 9] = [
        (-0.5, None),
        (0.0, Some(7.0)),
        (0.25, Some(8.75)),
        (0.5, Some(10.5)),
        (0.75, Some(9.25)),
        (1.0, Some(8.0)),
        (1.5, Some(8.5)),
        (2.0, Some(9.0)),
        (2.5, None),
    ];
    for (t, expected) in expected {
        assert_eq!(
            expect_number(property.get_value_option(t)),
            expected,
            "t = {}",
            t
        );
    }
}

// ---------------------------------------------------------------------------
// case 3: Hermite Number with two derivative orders — ≤ 2 ULP
// ---------------------------------------------------------------------------

#[test]
fn golden_hermite_multi_derivative_within_2_ulp() {
    let mut property = SampledProperty::with_derivative_types(
        PackableType::Number,
        Some(vec![PackableType::Number, PackableType::Number]),
    );
    property.set_forward_extrapolation_type(ExtrapolationType::Extrapolate);
    property.set_interpolation_options(Some(InterpolationAlgorithmKind::Hermite), Some(1));

    // Exact JS `Math.sin` / `Math.cos` inputs (V8 doubles) so the Rust side
    // never needs its own transcendental evaluation of the inputs.
    let samples: [(f64, f64, [f64; 2]); 5] = [
        (0.0, 0.0, [1.0, -0.0]),
        (
            20.0,
            0.9129452507276277,
            [0.40808206181339196, -0.9129452507276277],
        ),
        (
            40.0,
            0.7451131604793488,
            [-0.6669380616522619, -0.7451131604793488],
        ),
        (
            60.0,
            -0.3048106211022167,
            [-0.9524129804151563, 0.3048106211022167],
        ),
        (
            80.0,
            -0.9938886539233752,
            [-0.11038724383904756, 0.9938886539233752],
        ),
    ];
    for (time, value, derivatives) in samples {
        property.add_sample_with_derivatives(
            time,
            &number(value),
            &[number(derivatives[0]), number(derivatives[1])],
        );
    }

    let expected: [(f64, f64); 12] = [
        (0.0, 0.0),
        (10.0, -3.399691634850708),
        (20.0, 0.9129452507276277),
        (30.0, -6.174397978609949),
        (40.0, 0.7451131604793488),
        (50.0, -1.6396304802844632),
        (60.0, -0.3048106211022167),
        (70.0, 4.836190404596815),
        (80.0, -0.9938886539233752),
        (90.0, 169.44896639154283), // forward extrapolation region
        (95.0, 611.3160981778776),
        (105.0, 3617.9201938560423),
    ];
    for (t, expected) in expected {
        let actual = expect_number(property.get_value_option(t))
            .unwrap_or_else(|| panic!("expected a value at t = {}", t));
        assert_epsilon_eq_f64!(actual, expected);
    }
}

// ---------------------------------------------------------------------------
// case 4: Hermite Cartesian3 (spec dataset), order 1 and order 0 — ≤ 2 ULP
// ---------------------------------------------------------------------------

const HERMITE_TIMES: [f64; 8] = [0.0, 60.0, 120.0, 180.0, 240.0, 300.0, 360.0, 420.0];

const HERMITE_POSITIONS: [[f64; 3]; 8] = [
    [13378137.0, 0.0, 1.0],
    [13374128.3576279, 327475.593690065, 2.0],
    [13362104.8328212, 654754.936954423, 3.0],
    [13342073.6310691, 981641.896976832, 4.0],
    [13314046.7567223, 1307940.57608951, 5.0],
    [13278041.005799, 1633455.42917117, 6.0],
    [13234077.9559193, 1957991.38083385, 7.0],
    [13182183.953374, 2281353.94232816, 8.0],
];

const HERMITE_DERIVATIVES: [[f64; 3]; 8] = [
    [0.0, 5458.47176691947, 0.0],
    [-133.614738921601, 5456.83618333919, 0.0],
    [-267.149404854867, 5451.93041277513, 0.0],
    [-400.523972797808, 5443.75739517027, 0.0],
    [-533.658513692378, 5432.32202847183, 0.0],
    [-666.473242324565, 5417.63116569613, 0.0],
    [-798.888565138278, 5399.69361082164, 0.0],
    [-930.82512793439, 5378.52011351288, 0.0],
];

fn hermite_queries() -> Vec<f64> {
    let mut queries: Vec<f64> = (0..=420).step_by(20).map(|t| t as f64).collect();
    queries.push(430.0); // out of range without extrapolation
    queries
}

fn check_hermite_series(property: &SampledProperty, expected: &[Option<[f64; 3]>]) {
    for (t, expected) in hermite_queries().into_iter().zip(expected.iter()) {
        let actual = expect_cartesian3(property.get_value_option(t));
        match expected {
            None => assert!(actual.is_none(), "t = {}: expected None", t),
            Some([x, y, z]) => {
                let [ax, ay, az] =
                    actual.unwrap_or_else(|| panic!("expected a value at t = {}", t));
                assert_epsilon_eq_f64!(ax, *x);
                assert_epsilon_eq_f64!(ay, *y);
                assert_epsilon_eq_f64!(az, *z);
            }
        }
    }
}

