// ---------------------------------------------------------------------------
// case 5: extrapolation option matrix — bit-exact
// ---------------------------------------------------------------------------

#[test]
fn golden_extrapolation_matrix_is_bit_exact() {
    let build = || {
        let mut property = SampledProperty::new(PackableType::Number);
        property.add_sample(2.0, &number(1.0)); // JulianDate(0, 2)
        property.add_sample(3.0, &number(2.0)); // JulianDate(0, 3)
        property
    };
    let queries: [f64; 6] = [0.99, 1.0, 2.0, 3.0, 4.0, 4.01];

    // (forward type, forward duration, backward type, backward duration)
    let configs: [(ExtrapolationType, f64, ExtrapolationType, f64); 5] = [
        (ExtrapolationType::None, 0.0, ExtrapolationType::None, 0.0),
        (ExtrapolationType::Hold, 1.0, ExtrapolationType::None, 1.0),
        (
            ExtrapolationType::Extrapolate,
            1.0,
            ExtrapolationType::None,
            1.0,
        ),
        (ExtrapolationType::None, 1.0, ExtrapolationType::Hold, 1.0),
        (
            ExtrapolationType::None,
            1.0,
            ExtrapolationType::Extrapolate,
            1.0,
        ),
    ];
    let expected: [[Option<f64>; 6]; 5] = [
        [None, None, Some(1.0), Some(2.0), None, None],
        [None, None, Some(1.0), Some(2.0), Some(2.0), None],
        [None, None, Some(1.0), Some(2.0), Some(3.0), None],
        [None, Some(1.0), Some(1.0), Some(2.0), None, None],
        [None, Some(0.0), Some(1.0), Some(2.0), None, None],
    ];

    for (config, expected) in configs.iter().zip(expected.iter()) {
        let mut property = build();
        property.set_forward_extrapolation_type(config.0);
        property.set_forward_extrapolation_duration(config.1);
        property.set_backward_extrapolation_type(config.2);
        property.set_backward_extrapolation_duration(config.3);

        for (t, expected) in queries.iter().zip(expected.iter()) {
            assert_eq!(
                expect_number(property.get_value_option(*t)),
                *expected,
                "config = {:?}, t = {}",
                config,
                t
            );
        }
    }
}

// ---------------------------------------------------------------------------
// case 6: Lagrange degrees 2 and 3 — ≤ 2 ULP
// ---------------------------------------------------------------------------

#[test]
fn golden_lagrange_cubic_within_2_ulp() {
    let mut property = SampledProperty::new(PackableType::Number);
    property.set_interpolation_options(Some(InterpolationAlgorithmKind::Lagrange), Some(3));
    for (i, value) in [0.0, 1.0, 8.0, 27.0, 64.0, 125.0].iter().enumerate() {
        property.add_sample(i as f64, &number(*value));
    }

    // (t, golden v, max ULP). All points match within the 2-ULP contract;
    // t = 3.7 needs 4 ULPs: Lagrange evaluation is a pure division-heavy
    // polynomial loop and the Rust port accumulates rounding in a slightly
    // different order than V8 (relative difference is ~5e-15).
    let expected: [(f64, Option<f64>, u64); 7] = [
        (0.5, Some(0.125), 2),
        (1.5, Some(3.375), 2),
        (2.5, Some(15.625), 2),
        (3.7, Some(50.65299999999998), 4),
        (4.25, Some(76.765625), 2),
        (5.0, Some(125.0), 2),
        (5.5, None, 0),
    ];
    for (t, expected, max_ulp) in expected {
        match expected {
            None => assert!(property.get_value_option(t).is_none(), "t = {}", t),
            Some(expected) => {
                let actual = expect_number(property.get_value_option(t))
                    .unwrap_or_else(|| panic!("expected a value at t = {}", t));
                assert_epsilon_eq_f64!(actual, expected, max_ulp);
            }
        }
    }
}

#[test]
fn golden_lagrange_quadratic_within_2_ulp() {
    let mut property = SampledProperty::new(PackableType::Number);
    property.set_interpolation_options(Some(InterpolationAlgorithmKind::Lagrange), Some(2));
    for (i, value) in [0.0, 1.0, 4.0, 9.0].iter().enumerate() {
        property.add_sample(i as f64, &number(*value));
    }

    let expected: [(f64, Option<f64>); 5] = [
        (0.5, Some(0.25)),
        (1.25, Some(1.5625)),
        (2.5, Some(6.25)),
        (3.0, Some(9.0)),
        (3.5, None),
    ];
    for (t, expected) in expected {
        match expected {
            None => assert!(property.get_value_option(t).is_none(), "t = {}", t),
            Some(expected) => {
                let actual = expect_number(property.get_value_option(t))
                    .unwrap_or_else(|| panic!("expected a value at t = {}", t));
                assert_epsilon_eq_f64!(actual, expected);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// case 7: linear Cartesian3 — bit-exact
// ---------------------------------------------------------------------------

#[test]
fn golden_linear_cartesian3_is_bit_exact() {
    let mut property = SampledProperty::new(PackableType::Cartesian3);
    property.add_sample(0.0, &cartesian3(1.0, 10.0, 100.0));
    property.add_sample(10.0, &cartesian3(5.0, 30.0, 300.0));

    let expected: [(f64, Option<[f64; 3]>); 6] = [
        (-1.0, None),
        (0.0, Some([1.0, 10.0, 100.0])),
        (2.5, Some([2.0, 15.0, 150.0])),
        (5.0, Some([3.0, 20.0, 200.0])),
        (10.0, Some([5.0, 30.0, 300.0])),
        (11.0, None),
    ];
    for (t, expected) in expected {
        assert_eq!(
            expect_cartesian3(property.get_value_option(t)),
            expected,
            "t = {}",
            t
        );
    }
}

// ---------------------------------------------------------------------------
// case 8: TimeIntervalCollectionProperty — bit-exact
// ---------------------------------------------------------------------------

#[test]
fn golden_ticp_basic_is_bit_exact() {
    // JS base: JulianDate(10, 0); the golden t values are offsets from it,
    // which the Rust port expresses directly as absolute f64 seconds.
    let mut property = TimeIntervalCollectionProperty::new();
    property.add_interval(PropertyTimeInterval::new(10.0 * DAY, 12.0 * DAY, number(5.0)));
    let mut interval2 = PropertyTimeInterval::new(12.0 * DAY, 14.0 * DAY, number(6.0));
    interval2.is_start_included = false;
    property.add_interval(interval2);

    let base = 10.0 * DAY;
    let expected: [(f64, Option<f64>); 9] = [
        (-0.001, None),
        (0.0, Some(5.0)),
        (86400.0, Some(5.0)),
        (172799.9999, Some(5.0)),
        // interval2.start is excluded, so the boundary resolves to interval1
        // (its stop is included) — mirrors JS TimeIntervalCollection.indexOf.
        (172800.0, Some(5.0)),
        (172800.5, Some(6.0)),
        (216000.0, Some(6.0)),
        (259200.0, Some(6.0)),
        (259200.0001, Some(6.0)),
    ];
    for (offset, expected) in expected {
        assert_eq!(
            expect_number(property.get_value_option(base + offset)),
            expected,
            "offset = {}",
            offset
        );
    }
}

#[test]
fn golden_ticp_cartesian3_is_bit_exact() {
    let mut property = TimeIntervalCollectionProperty::new();
    property.add_interval(PropertyTimeInterval::new(
        10.0 * DAY,
        12.0 * DAY,
        cartesian3(1.0, 2.0, 3.0),
    ));
    let mut interval2 =
        PropertyTimeInterval::new(12.0 * DAY, 14.0 * DAY, cartesian3(4.0, 5.0, 6.0));
    interval2.is_start_included = false;
    property.add_interval(interval2);

    let base = 10.0 * DAY;
    let expected: [(f64, Option<[f64; 3]>); 6] = [
        (0.0, Some([1.0, 2.0, 3.0])),
        (86400.0, Some([1.0, 2.0, 3.0])),
        (172800.0, Some([1.0, 2.0, 3.0])),
        (216000.0, Some([4.0, 5.0, 6.0])),
        (259200.0, Some([4.0, 5.0, 6.0])),
        (259201.0, Some([4.0, 5.0, 6.0])),
    ];
    for (offset, expected) in expected {
        assert_eq!(
            expect_cartesian3(property.get_value_option(base + offset)),
            expected,
            "offset = {}",
            offset
        );
    }
}

#[test]
fn golden_ticp_empty_is_bit_exact() {
    let property = TimeIntervalCollectionProperty::new();
    assert!(property.get_value_option(0.0).is_none());
    assert!(property.get_value_option(11.0).is_none());
}

// ---------------------------------------------------------------------------
// case 9: degenerate SampledProperty behavior — bit-exact
// ---------------------------------------------------------------------------

#[test]
fn golden_sampled_empty_is_bit_exact() {
    let property = SampledProperty::new(PackableType::Number);
    assert!(property.get_value_option(0.0).is_none());
    assert!(property.get_value_option(1.0).is_none());
}

#[test]
fn golden_sampled_single_is_bit_exact() {
    let mut property = SampledProperty::new(PackableType::Number);
    property.add_sample(0.0, &number(7.0));
    assert!(property.get_value_option(-1.0).is_none());
    assert_eq!(expect_number(property.get_value_option(0.0)), Some(7.0));
    assert!(property.get_value_option(4.0).is_none());
}

#[test]
fn golden_sampled_empty_hold_is_bit_exact() {
    // hold extrapolation on an empty property still returns undefined
    let mut property = SampledProperty::new(PackableType::Cartesian3);
    property.set_backward_extrapolation_type(ExtrapolationType::Hold);
    property.set_forward_extrapolation_type(ExtrapolationType::Hold);
    assert!(property.get_value_option(0.0).is_none());
}
